<?php
namespace App\Services\DevOps;use App\Models\ZigoDevOpsAudit;use Illuminate\Http\Request;
final class DevOpsAuditService {public function record(string $action,string $result,?string $environment=null,?int $deploymentId=null,array $metadata=[],?Request $request=null):ZigoDevOpsAudit{$request??=request();return ZigoDevOpsAudit::create(['user_id'=>auth()->id(),'action'=>$action,'environment'=>$environment,'deployment_id'=>$deploymentId,'result'=>$result,'ip_hash'=>$this->hash($request?->ip()),'user_agent_hash'=>$this->hash($request?->userAgent()),'metadata'=>$this->sanitize($metadata)]);}private function hash(?string $value):?string{return filled($value)?hash_hmac('sha256',$value,(string)config('app.key')):null;}private function sanitize(array $data):array{foreach($data as $key=>$value){if(preg_match('/secret|token|password|authorization|api.?key/i',(string)$key))$data[$key]='[REDACTED]';elseif(is_array($value))$data[$key]=$this->sanitize($value);}return$data;}}
